CREATE TABLE IF NOT EXISTS gis_phase373_fetch_jobs (dataset_key TEXT PRIMARY KEY, source_url TEXT NOT NULL, layer_name TEXT NOT NULL, fetch_offset BIGINT NOT NULL DEFAULT 0, page_size INTEGER NOT NULL DEFAULT 10, status TEXT NOT NULL DEFAULT 'PENDING', total_loaded BIGINT NOT NULL DEFAULT 0, last_error TEXT, last_run_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS gis_phase373_fetch_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dataset_key TEXT NOT NULL, offset_start BIGINT NOT NULL, offset_end BIGINT NOT NULL, fetched BIGINT NOT NULL DEFAULT 0, loaded BIGINT NOT NULL DEFAULT 0, status TEXT NOT NULL, error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());